1	import { createServerClient } from '@supabase/ssr'
2	import { NextResponse } from 'next/server'
3	import { NextRequest } from 'next/server'
4	
5	export async function GET(request: NextRequest) {
6	  const { searchParams } = new URL(request.url)
7	  const code = searchParams.get('code')
8	
9	  // Get the actual origin from request headers (for proxy support)
10	  const forwardedHost = request.headers.get('x-forwarded-host');
11	  const forwardedProto = request.headers.get('x-forwarded-proto');
12	  const host = forwardedHost || request.headers.get('host') || 'localhost:9002';
13	  const protocol = forwardedProto || 'http';
14	  const origin = `${protocol}://${host}`;
15	
16	  // OAuth リダイレクト先を複数ソースから取得（優先順位順）
