const updateMemberTeamsSchema = z.object({
    memberId: z.string().uuid(),
    teamIds: z.array(z.string().uuid()),
});

export async function updateMemberTeams(memberId: string, teamIds: string[]): Promise<{ error: string | null }> {
    const parsed = updateMemberTeamsSchema.safeParse({ memberId, teamIds });
    if (!parsed.success) return { error: '無効なパラメータです。' };

    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return { error: '認証が必要です。' };

    const { data: admin } = await supabase.from('members').select('is_admin').eq('supabase_auth_user_id', user.id).single();
    if (!admin?.is_admin) return { error: '管理者権限が必要です。' };

    try {
        const { error: deleteError } = await supabase
            .from('member_team_relations')
            .delete()
            .eq('member_id', memberId);

        if (deleteError) throw deleteError;

        if (teamIds.length > 0) {
            const newRelations = teamIds.map(teamId => ({
                member_id: memberId,
                team_id: teamId,
            }));
            const { error: insertError } = await supabase
                .from('member_team_relations')
                .insert(newRelations);

            if (insertError) throw insertError;
        }

        const { data: member } = await supabase.from('members').select('discord_uid').eq('supabase_auth_user_id', memberId).single();
        if (member) {
            await syncDiscordRoles(member.discord_uid);
        }

        revalidatePath('/dashboard/admin/members');
        revalidatePath('/dashboard/admin/teams');
        return { error: null };
    } catch (e: any) {
        console.error("Error updating member teams:", e);
        return { error: e.message };
    }
}


export async function syncAllDiscordRoles(): Promise<{ error: string | null, message: string }> {
    try {
        await checkAdmin();
        const apiUrl = process.env.NEXT_PUBLIC_STEM_BOT_API_URL;
        const token = process.env.STEM_BOT_API_BEARER_TOKEN;

        if (!apiUrl || !token) {
            throw new Error('API URL or Bearer Token is not configured for Discord role sync.');
        }

        const res = await fetch(`${apiUrl}/api/roles/sync-all`, {
            method: 'POST',
            headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
            cache: 'no-store',
        });

        const result = await res.json();

        if (!res.ok || !result.success) {
            const errorMessage = result.error || `API returned status ${res.status}`;
            console.error('[Discord Bot] Failed to sync all roles.', errorMessage);
            throw new Error(errorMessage);
        }

        if (result.message === 'No members to sync') {
             return { error: null, message: '同期対象のメンバーが見つかりませんでした。' };
        }

        const successMessage = `${result.synced}人の同期に成功しました。`;
        const failureMessage = result.failed > 0 ? `${result.failed}人の同期に失敗しました。` : '';
        const totalMessage = `(合計: ${result.total}人)`;

        let finalMessage = `${successMessage} ${failureMessage} ${totalMessage}`.trim();
        if (result.errors && result.errors.length > 0) {
            console.error('[Discord Bot] Sync-all errors:', result.errors);
        }

        return { error: null, message: finalMessage };

    } catch (e: any) {
        return { error: e.message, message: '' };
    }
}

const updateStatusesSchema = z.object({
    highSchoolFirstYearGeneration: z.number().int().positive(),
});

export async function updateStatusesForNewAcademicYear(highSchoolFirstYearGeneration: number): Promise<{ error: string | null, message: string }> {
    try {
        await checkAdmin();
        const parsed = updateStatusesSchema.safeParse({ highSchoolFirstYearGeneration });
        if (!parsed.success) {
            return { error: '有効な期数を指定してください。', message: '' };
        }

        const supabase = await createAdminClient();

        const highSchoolGenerations = [
            highSchoolFirstYearGeneration,      // 1st year
            highSchoolFirstYearGeneration - 1,  // 2nd year
            highSchoolFirstYearGeneration - 2   // 3rd year
        ];
        const juniorHighSchoolGenerations = [
            highSchoolFirstYearGeneration + 1,  // 3rd year
            highSchoolFirstYearGeneration + 2,  // 2nd year
            highSchoolFirstYearGeneration + 3   // 1st year
        ];

        const allStudentGenerations = [...highSchoolGenerations, ...juniorHighSchoolGenerations];

        console.log('[年度更新] 高校生の期:', highSchoolGenerations);
        console.log('[年度更新] 中学生の期:', juniorHighSchoolGenerations);
        console.log('[年度更新] 在籍中の期（全）:', allStudentGenerations);

        // Get count before update for better message
        const { count: totalMembers, error: countError } = await supabase
            .from('members')
            .select('*', { count: 'exact', head: true })
            .is('deleted_at', null);

        if (countError) throw new Error(`メンバー数の取得に失敗: ${countError.message}`);


        // Update High School Students
        const { error: hsError, data: hsData } = await supabase
            .from('members')
            .update({ status: 1 }) // 1: High School
            .in('generation', highSchoolGenerations)
            .is('deleted_at', null)
            .select();
        if (hsError) throw new Error(`高校生の更新に失敗: ${hsError.message}`);
        console.log(`[年度更新] 高校生に更新: ${hsData?.length || 0}人`);

        // Update Junior High School Students
        const { error: jhsError, data: jhsData } = await supabase
            .from('members')
            .update({ status: 0 }) // 0: Junior High
            .in('generation', juniorHighSchoolGenerations)
            .is('deleted_at', null)
            .select();
        if (jhsError) throw new Error(`中学生の更新に失敗: ${jhsError.message}`);
        console.log(`[年度更新] 中学生に更新: ${jhsData?.length || 0}人`);

        // Update OB/OG (期が在籍中リストに含まれないメンバー)
        const { error: obError, data: obData } = await supabase
            .from('members')
            .update({ status: 2 }) // 2: OB/OG
            .not('generation', 'in', `(${allStudentGenerations.join(',')})`)
            .is('deleted_at', null)
            .select();
        if (obError) {
            console.error('[年度更新] OB/OG更新エラー:', obError);
            throw new Error(`OB/OGの更新に失敗: ${obError.message}`);
        }
        console.log(`[年度更新] OB/OGに更新: ${obData?.length || 0}人`, obData);

        // Re-sync all members' roles
        await syncAllDiscordRoles();

        revalidatePath('/dashboard/admin/members');

        return { error: null, message: `全${totalMembers || 0}人のメンバーのステータスを更新し、ロールの同期を開始しました。` };

    } catch (e: any) {
        console.error("Failed to update for new academic year:", e);
        return { error: e.message, message: '' };
    }
}


export async function renameGraduatesToNewFormat(): Promise<{ error: string | null, message: string }> {
    try {
        await checkAdmin();
        const supabase = await createAdminClient();

        const { data: obMembers, error: fetchError } = await supabase
            .from('members')
            .select('supabase_auth_user_id, discord_uid')
            .eq('status', 2)
            .is('deleted_at', null)
            .not('discord_uid', 'is', null);

        if (fetchError) throw new Error(`OB/OGメンバーの取得に失敗: ${fetchError.message}`);
        if (!obMembers || obMembers.length === 0) {
            return { error: null, message: 'OB/OGメンバーが見つかりませんでした。' };
        }

        const { data: { users: allUsers }, error: usersError } = await supabase.auth.admin.listUsers({ page: 1, perPage: 1000 });
        if (usersError) throw new Error(`ユーザー情報の取得に失敗: ${usersError.message}`);

        const userMap = new Map(allUsers.map(u => [u.id, u]));

        let successCount = 0;
        let failCount = 0;

        for (const member of obMembers) {
            const user = userMap.get(member.supabase_auth_user_id);
            if (!user || !member.discord_uid) { failCount++; continue; }
            const fullName = ((user.user_metadata?.last_name ?? '') + (user.user_metadata?.first_name ?? '')).replace(/\s/g, '');
            if (!fullName) {
                failCount++;
                console.error(`[renameGraduates] Skipping ${member.discord_uid}: 本名(last_name/first_name)が取得できません。`);
                continue;
            }
            await syncDiscordNickname(member.discord_uid, fullName);
            successCount++;
        }

        return {
            error: null,
            message: `${successCount}人の卒業生のニックネームを「名前(第n期卒業生)」形式に更新しました。${failCount > 0 ? `（${failCount}人は名前情報なしのためスキップ）` : ''}`,
        };
    } catch (e: any) {
        console.error('Failed to rename graduates:', e);
        return { error: e.message, message: '' };
    }
}

